#[derive(Deserialize)]
struct DirectUserNameValidationQuery {
    name: Option<String>,
}

#[derive(Serialize)]
struct DirectUserNameValidationResponse {
    #[serde(rename = "isExist")]
    is_exist: bool,
    #[serde(rename = "isReserved")]
    is_reserved: bool,
}

#[derive(Deserialize)]
struct DirectUserEmailValidationQuery {
    email: Option<String>,
}

#[derive(Serialize)]
struct DirectUserEmailValidationResponse {
    #[serde(rename = "isExist")]
    is_exist: bool,
}

async fn direct_legacy_user_name_validation(
    query: DirectUserNameValidationQuery,
    backend: PilotBackend,
) -> Response {
    let name = query.name.unwrap_or_default();
    let is_reserved = is_legacy_reserved_user_name(&name);
    let PilotBackend::Repository(repository) = backend else {
        return RestRouteError::not_implemented("signup validation requires repository backend")
            .into_response();
    };

    let user_exists = match repository.user_login_id_exists(&name).await {
        Ok(exists) => exists,
        Err(error) => return RestRouteError::internal(error.to_string()).into_response(),
    };
    let organization_exists = if user_exists {
        false
    } else {
        match repository.organization_name_exists(&name).await {
            Ok(exists) => exists,
            Err(error) => return RestRouteError::internal(error.to_string()).into_response(),
        }
    };

    Json(DirectUserNameValidationResponse {
        is_exist: user_exists || organization_exists,
        is_reserved,
    })
    .into_response()
}

async fn direct_legacy_user_email_validation(
    query: DirectUserEmailValidationQuery,
    backend: PilotBackend,
) -> Response {
    let email = query.email.unwrap_or_default();
    let PilotBackend::Repository(repository) = backend else {
        return RestRouteError::not_implemented("signup validation requires repository backend")
            .into_response();
    };
    let is_exist = match repository.user_email_exists(&email).await {
        Ok(exists) => exists,
        Err(error) => return RestRouteError::internal(error.to_string()).into_response(),
    };

    Json(DirectUserEmailValidationResponse { is_exist }).into_response()
}

fn is_legacy_reserved_user_name(name: &str) -> bool {
    let normalized = normalize_identifier(name);
    LEGACY_RESERVED_USER_NAMES
        .iter()
        .any(|reserved| normalize_identifier(reserved) == normalized)
}

async fn direct_legacy_logout(
    headers: HeaderMap,
    session_manager: SessionManager,
    base_path: String,
) -> Response {
    let redirect_target = headers
        .get(http::header::REFERER)
        .and_then(|value| value.to_str().ok())
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string)
        .unwrap_or_else(|| base_path_href(&base_path, "/"));
    let previous_token = session_manager
        .read_session_from_headers(&headers)
        .map(|session| session.token);
    let anonymous_session = session_manager.create_anonymous_session(previous_token.as_deref());

    let mut ctx = Context::new(headers);
    attach_session_headers(&mut ctx, &session_manager, &anonymous_session);
    let mut response = Redirect::to(&redirect_target).into_response();
    append_response_headers(response.headers_mut(), &ctx.response_headers);
    response
}

async fn direct_legacy_leave_project(
    mut headers: HeaderMap,
    owner_name: String,
    project_name: String,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
) -> Response {
    let login_redirect = base_path_href(
        &base_path,
        "/users/loginform?redirectUrl=%2Fuser%2Feditform",
    );
    let Some(session) = session_manager.read_session_from_headers(&headers) else {
        return Redirect::to(&login_redirect).into_response();
    };
    let Some(user_id) = session.user_id else {
        return Redirect::to(&login_redirect).into_response();
    };
    let PilotBackend::Repository(repository) = &backend else {
        return RestRouteError::not_implemented("project leave requires repository backend")
            .into_response();
    };
    let user = match repository.find_user_by_id(user_id).await {
        Ok(Some(user)) => user,
        Ok(None) => return RestRouteError::not_found("user not found").into_response(),
        Err(error) => return RestRouteError::internal(error.to_string()).into_response(),
    };
    headers.insert(
        "x-csrf-token",
        HeaderValue::from_str(&session.csrf_token).expect("csrf token header"),
    );
    let service = PilotServiceImpl {
        base_path: base_path.clone(),
        public_origin: String::new(),
        session_manager,
        backend,
    };
    let _ = rest_delete_project_member(headers, owner_name, project_name, user_id, service).await;
    redirect_to(
        &base_path,
        &format!("/{}?daysAgo=14&selected=projects", user.login_id),
    )
}

