#[derive(Deserialize)]
#[serde(untagged)]
enum RestStringOrNumber {
    String(String),
    Signed(i64),
    Unsigned(u64),
}

fn parse_rest_i64(value: RestStringOrNumber) -> Result<i64, String> {
    match value {
        RestStringOrNumber::String(value) => value
            .trim()
            .parse::<i64>()
            .map_err(|_| format!("invalid integer value: {value}")),
        RestStringOrNumber::Signed(value) => Ok(value),
        RestStringOrNumber::Unsigned(value) => {
            i64::try_from(value).map_err(|_| format!("integer is too large: {value}"))
        }
    }
}

fn deserialize_optional_i64_from_string_or_number<'de, D>(
    deserializer: D,
) -> Result<Option<i64>, D::Error>
where
    D: Deserializer<'de>,
{
    let value = Option::<RestStringOrNumber>::deserialize(deserializer)?;
    value
        .map(parse_rest_i64)
        .transpose()
        .map_err(serde::de::Error::custom)
}

fn deserialize_i64_vec_from_strings_or_numbers<'de, D>(
    deserializer: D,
) -> Result<Vec<i64>, D::Error>
where
    D: Deserializer<'de>,
{
    let values = Vec::<RestStringOrNumber>::deserialize(deserializer)?;
    values
        .into_iter()
        .map(parse_rest_i64)
        .collect::<Result<Vec<_>, _>>()
        .map_err(serde::de::Error::custom)
}

#[derive(Default, Deserialize)]
#[serde(rename_all = "camelCase", default)]
struct RestProjectIssuesQuery {
    assignee_id: Option<i64>,
    assignee_login_id: String,
    author_login_id: String,
    label_ids: Vec<i64>,
    milestone_id: Option<i64>,
    page_num: u32,
    state: String,
}

#[derive(Default, Deserialize)]
#[serde(rename_all = "camelCase", default)]
struct RestOrganizationIssuesQuery {
    assignee_id: i64,
    author_id: i64,
    filter: String,
    items_per_page: u32,
    order_by: String,
    order_dir: String,
    page_num: u32,
    project_names: Vec<String>,
    state: String,
}

impl RestOrganizationIssuesQuery {
    fn from_raw_query(raw_query: Option<&str>) -> Result<Self, RestRouteError> {
        let mut query = Self::default();
        let Some(raw_query) = raw_query else {
            return Ok(query);
        };

        for pair in raw_query.split('&').filter(|pair| !pair.is_empty()) {
            let (raw_key, raw_value) = pair.split_once('=').unwrap_or((pair, ""));
            let key = decode_query_component(raw_key);
            let value = decode_query_component(raw_value);
            match key.as_str() {
                "assigneeId" => query.assignee_id = parse_rest_query_i64(&value)?,
                "authorId" => query.author_id = parse_rest_query_i64(&value)?,
                "filter" => query.filter = value,
                "itemsPerPage" => query.items_per_page = parse_rest_query_u32(&value)?,
                "orderBy" => query.order_by = value,
                "orderDir" => query.order_dir = value,
                "pageNum" => query.page_num = parse_rest_query_u32(&value)?,
                "projectNames" | "projectNames[]" => {
                    if !value.trim().is_empty() {
                        query.project_names.push(value);
                    }
                }
                "state" => query.state = value,
                _ => {}
            }
        }

        Ok(query)
    }
}

fn parse_rest_query_i64(value: &str) -> Result<i64, RestRouteError> {
    if value.trim().is_empty() {
        return Ok(0);
    }
    value
        .parse()
        .map_err(|_| RestRouteError::bad_request("invalid organization issue query"))
}

fn parse_rest_query_u32(value: &str) -> Result<u32, RestRouteError> {
    if value.trim().is_empty() {
        return Ok(0);
    }
    value
        .parse()
        .map_err(|_| RestRouteError::bad_request("invalid organization issue query"))
}

fn decode_query_component(value: &str) -> String {
    let bytes = value.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        match bytes[index] {
            b'+' => {
                decoded.push(b' ');
                index += 1;
            }
            b'%' if index + 2 < bytes.len() => {
                let high = (bytes[index + 1] as char).to_digit(16);
                let low = (bytes[index + 2] as char).to_digit(16);
                if let (Some(high), Some(low)) = (high, low) {
                    decoded.push(((high << 4) | low) as u8);
                    index += 3;
                } else {
                    decoded.push(bytes[index]);
                    index += 1;
                }
            }
            byte => {
                decoded.push(byte);
                index += 1;
            }
        }
    }

    String::from_utf8_lossy(&decoded).into_owned()
}

