async fn direct_create_issue_comment(
    headers: HeaderMap,
    owner: String,
    project: String,
    issue_number: i64,
    form: HashMap<String, String>,
    session_manager: SessionManager,
    backend: PilotBackend,
    base_path: String,
    public_origin: String,
) -> Response {
    match rest_create_issue_comment(
        headers_with_form_csrf(headers, &form),
        owner.clone(),
        project.clone(),
        issue_number,
        direct_issue_comment_body(&form),
        session_manager,
        backend,
        base_path.clone(),
        public_origin,
    )
    .await
    {
        Ok(Json(detail)) => {
            let fragment = detail
                .detail
                .comments
                .iter()
                .max_by_key(|comment| comment.id)
                .map(|comment| format!("#comment-{}", comment.id))
                .unwrap_or_default();
            redirect_to(
                &base_path,
                &format!("/{owner}/{project}/issue/{issue_number}{fragment}"),
            )
        }
        Err(error) => error.into_response(),
    }
}

