async fn rest_pull_request_detail_from_record_with_repository_issue_references(
    repository: &PilotRepository,
    record: persistence::PullRequestDetailRecord,
    authorization: &persistence::ProjectAuthorizationRecord,
    actor_id: Option<i64>,
    base_path: &str,
) -> Result<RestPullRequestDetailResponse, ConnectError> {
    let source_branch_state =
        rest_pull_request_source_branch_state(repository, &record, actor_id).await?;
    let mut markdowns = vec![record.body_markdown.as_str()];
    for thread in &record.threads {
        markdowns.extend(
            thread
                .comments
                .iter()
                .map(|comment| comment.contents_markdown.as_str()),
        );
    }
    let issue_references =
        markdown_issue_references_for_project(repository, authorization, actor_id, &markdowns)
            .await?;
    rest_pull_request_detail_from_record_with_issue_references(
        record,
        authorization,
        actor_id,
        base_path,
        &issue_references,
        source_branch_state,
    )
}

async fn rest_pull_request_source_branch_state(
    repository: &PilotRepository,
    record: &persistence::PullRequestDetailRecord,
    actor_id: Option<i64>,
) -> Result<RestPullRequestSourceBranchState, ConnectError> {
    let Some(source_project) = repository
        .read_project_by_owner_and_name(&record.from_owner_name, &record.from_project_name)
        .await
        .map_err(internal_error)?
    else {
        return Ok(RestPullRequestSourceBranchState::default());
    };
    if !source_project.vcs.eq_ignore_ascii_case("GIT") {
        return Ok(RestPullRequestSourceBranchState::default());
    }

    let repo_path = yona_rust_vcs::repository_path(&yona_data_root(), source_project.id);
    let snapshot = yona_rust_vcs::read_branch_list(&repo_path).map_err(code_browser_error)?;
    let branch = snapshot
        .branches
        .iter()
        .find(|branch| branch.name == record.from_branch);
    let exists = branch.is_some();
    let is_default = branch.is_some_and(|branch| branch.is_default);
    let viewer_is_contributor =
        actor_id.is_some_and(|actor_id| actor_id == record.contributor.user_id);
    let is_merged = record.state == "merged";
    let can_delete = viewer_is_contributor && is_merged && exists && !is_default;
    let can_restore = viewer_is_contributor
        && is_merged
        && !exists
        && !record.merged_commit_id_to.trim().is_empty();

    Ok(RestPullRequestSourceBranchState {
        can_delete,
        can_restore,
        exists,
    })
}

fn rest_pull_request_detail_from_record_with_issue_references(
    record: persistence::PullRequestDetailRecord,
    authorization: &persistence::ProjectAuthorizationRecord,
    actor_id: Option<i64>,
    _base_path: &str,
    issue_references: &[MarkdownIssueReference],
    source_branch_state: RestPullRequestSourceBranchState,
) -> Result<RestPullRequestDetailResponse, ConnectError> {
    let viewer_can_project_update = actor_id.is_some() && project_update_allowed(authorization)?;
    let viewer_is_contributor =
        actor_id.is_some_and(|user_id| user_id == record.contributor.user_id);
    let viewer_is_receiver = actor_id.is_some_and(|user_id| user_id == record.receiver.user_id);
    let viewer_is_reviewer = actor_id.is_some_and(|user_id| {
        record
            .reviewers
            .iter()
            .any(|reviewer| reviewer.user_id == user_id)
    });
    let can_update = viewer_can_project_update || viewer_is_contributor || viewer_is_receiver;
    let can_review = actor_id.is_some()
        && (authorization.viewer.is_project_member
            || authorization.viewer.is_project_manager
            || authorization.viewer.is_organization_admin
            || authorization.viewer.is_site_admin
            || viewer_is_receiver
            || viewer_is_reviewer);
    let can_moderate_review_comments = actor_id.is_some()
        && (authorization.viewer.is_project_member
            || authorization.viewer.is_project_manager
            || authorization.viewer.is_organization_admin
            || authorization.viewer.is_site_admin);
    let owner_name = record.owner_name.clone();
    let project_name = record.project_name.clone();
    Ok(RestPullRequestDetailResponse {
        body_html: String::new(),
        body_markdown: record.body_markdown,
        commits: record
            .commits
            .into_iter()
            .map(rest_pull_request_commit_from_record)
            .collect(),
        conflict: record.conflict,
        contributor: rest_pull_request_user_from_record(record.contributor),
        created_label: record.created_label,
        events: record
            .events
            .into_iter()
            .map(|event| RestPullRequestEvent {
                created_label: event.created_label,
                event_type: event.event_type,
                id: event.id,
                new_value: event.new_value,
                old_value: event.old_value,
                sender_login_id: event.sender_login_id,
            })
            .collect(),
        from_branch: record.from_branch,
        from_owner_name: record.from_owner_name,
        from_project_name: record.from_project_name,
        id: record.id,
        issue_references: issue_references
            .iter()
            .map(rest_issue_reference_metadata_from_resolved)
            .collect(),
        is_watching: record.is_watching,
        lacking_reviewer_count: record.lacking_reviewer_count,
        merged_commit_id_from: record.merged_commit_id_from,
        merged_commit_id_to: record.merged_commit_id_to,
        owner_name: owner_name.clone(),
        permissions: RestPullRequestPermissions {
            can_comment: actor_id.is_some(),
            can_delete_source_branch: source_branch_state.can_delete,
            can_read: true,
            can_read_changes: true,
            can_review,
            can_restore_source_branch: source_branch_state.can_restore,
            can_update,
            can_update_state: can_update,
        },
        project_name: project_name.clone(),
        pull_request_number: record.pull_request_number,
        receiver: rest_pull_request_user_from_record(record.receiver),
        required_reviewer_count: record.required_reviewer_count,
        reviewed: record.reviewed,
        reviewers: record
            .reviewers
            .into_iter()
            .map(rest_pull_request_user_from_record)
            .collect(),
        source_branch_exists: source_branch_state.exists,
        state: record.state,
        threads: record
            .threads
            .into_iter()
            .map(|thread| {
                rest_pull_request_thread_from_record(
                    thread,
                    actor_id,
                    can_moderate_review_comments,
                    issue_references,
                )
            })
            .collect(),
        title: record.title,
        to_branch: record.to_branch,
        updated_label: record.updated_label,
        watcher_count: record.watcher_count,
    })
}

fn code_browser_error(error: VcsError) -> ConnectError {
    match error {
        VcsError::GitUnavailable => ConnectError::unimplemented("git executable is unavailable"),
        VcsError::SvnAdminUnavailable => {
            ConnectError::unimplemented("svnadmin executable is unavailable")
        }
        VcsError::InvalidBranch | VcsError::InvalidPath | VcsError::InvalidRepositoryPath => {
            ConnectError::invalid_argument(error.to_string())
        }
        VcsError::NotFound => ConnectError::not_found("repository path not found"),
        VcsError::GitTimedOut
        | VcsError::GitFailed(_)
        | VcsError::SvnAdminFailed(_)
        | VcsError::SvnLookFailed(_)
        | VcsError::SvnLookUnavailable
        | VcsError::FilesystemFailed(_) => internal_error(error),
    }
}

fn code_branch_error(error: VcsError) -> ConnectError {
    match error {
        VcsError::GitUnavailable => ConnectError::unimplemented("git executable is unavailable"),
        VcsError::SvnAdminUnavailable => {
            ConnectError::unimplemented("svnadmin executable is unavailable")
        }
        VcsError::InvalidBranch | VcsError::InvalidPath | VcsError::InvalidRepositoryPath => {
            ConnectError::invalid_argument(error.to_string())
        }
        VcsError::NotFound => ConnectError::not_found("branch not found"),
        VcsError::GitTimedOut
        | VcsError::GitFailed(_)
        | VcsError::SvnAdminFailed(_)
        | VcsError::SvnLookFailed(_)
        | VcsError::SvnLookUnavailable
        | VcsError::FilesystemFailed(_) => internal_error(error),
    }
}

fn code_browser_response_from_snapshot(
    owner_name: &str,
    project_name: &str,
    snapshot: CodeBrowserSnapshot,
) -> ReadCodeBrowserResponse {
    ReadCodeBrowserResponse {
        branches: snapshot
            .branches
            .into_iter()
            .map(|branch| CodeBranch {
                name: branch.name,
                ..Default::default()
            })
            .collect(),
        breadcrumbs: snapshot
            .breadcrumbs
            .into_iter()
            .map(|breadcrumb| CodeBreadcrumb {
                name: breadcrumb.name,
                path: breadcrumb.path,
                ..Default::default()
            })
            .collect(),
        entries: snapshot
            .entries
            .into_iter()
            .map(code_entry_to_proto)
            .collect(),
        file: snapshot.file.map(code_file_to_proto).into(),
        no_head: snapshot.no_head,
        owner_name: owner_name.to_string(),
        path: snapshot.path,
        project_name: project_name.to_string(),
        selected_branch: snapshot.selected_branch,
        ..Default::default()
    }
}

fn code_browser_rest_response_from_snapshot(
    owner_name: &str,
    project_name: &str,
    snapshot: CodeBrowserSnapshot,
    base_path: &str,
) -> RestCodeBrowserResponse {
    let proto = code_browser_response_from_snapshot(owner_name, project_name, snapshot);
    let selected_branch = proto.selected_branch.clone();
    RestCodeBrowserResponse {
        branches: proto
            .branches
            .into_iter()
            .map(|branch| RestCodeBranch { name: branch.name })
            .collect(),
        breadcrumbs: proto
            .breadcrumbs
            .into_iter()
            .map(|breadcrumb| RestCodeBreadcrumb {
                name: breadcrumb.name,
                path: breadcrumb.path,
            })
            .collect(),
        entries: proto.entries,
        file: proto.file.into_option().map(|file| {
            code_file_to_rest(file, base_path, owner_name, project_name, &selected_branch)
        }),
        no_head: proto.no_head,
        owner_name: proto.owner_name,
        path: proto.path,
        project_name: proto.project_name,
        selected_branch,
    }
}

fn code_entry_to_proto(entry: CodeEntryRecord) -> CodeEntry {
    CodeEntry {
        commit_date: entry.commit_date,
        commit_message: entry.commit_message,
        commit_short_id: entry.commit_short_id,
        kind: entry.kind,
        name: entry.name,
        path: entry.path,
        size: entry.size,
        ..Default::default()
    }
}

fn code_file_to_rest(
    file: CodeFile,
    base_path: &str,
    owner_name: &str,
    project_name: &str,
    branch: &str,
) -> RestCodeFile {
    let (html, text) = if code_file_is_renderable_markdown(&file) {
        (
            String::new(),
            rewrite_code_browser_markdown_image_links(
                &file.text,
                base_path,
                owner_name,
                project_name,
                branch,
            ),
        )
    } else {
        (String::new(), file.text)
    };
    RestCodeFile {
        html,
        is_binary: file.is_binary,
        is_too_large: file.is_too_large,
        mime_type: file.mime_type,
        name: file.name,
        path: file.path,
        size: file.size,
        text,
    }
}

fn project_readme_file_from_git(
    repo_path: &StdPath,
    base_path: &str,
    owner_name: &str,
    project_name: &str,
) -> Result<Option<RestProjectReadmeFile>, ConnectError> {
    for candidate in [
        "README.md",
        "readme.md",
        "README.markdown",
        "readme.markdown",
    ] {
        match yona_rust_vcs::read_code_browser(repo_path, None, candidate) {
            Ok(snapshot) => {
                let Some(file) = snapshot.file else {
                    continue;
                };
                if !code_file_record_is_renderable_markdown(&file) {
                    continue;
                }
                let body_markdown = rewrite_project_readme_markdown_links(
                    &file.text,
                    base_path,
                    owner_name,
                    project_name,
                    &snapshot.selected_branch,
                );
                return Ok(Some(RestProjectReadmeFile {
                    body_html: String::new(),
                    body_markdown,
                    name: file.name,
                }));
            }
            Err(VcsError::NotFound) => continue,
            Err(error) => return Err(code_browser_error(error)),
        }
    }

    Ok(None)
}

fn code_file_is_renderable_markdown(file: &CodeFile) -> bool {
    !file.is_binary && !file.is_too_large && code_path_is_markdown(&file.path)
}

fn code_file_record_is_renderable_markdown(file: &CodeFileRecord) -> bool {
    !file.is_binary && !file.is_too_large && code_path_is_markdown(&file.path)
}

fn code_path_is_markdown(path: &str) -> bool {
    let extension = path
        .rsplit_once('.')
        .map(|(_, extension)| extension.to_ascii_lowercase())
        .unwrap_or_default();
    matches!(
        extension.as_str(),
        "markdown" | "mdown" | "mkdn" | "mkd" | "md" | "mdwn"
    )
}

fn code_file_to_proto(file: CodeFileRecord) -> CodeFile {
    CodeFile {
        is_binary: file.is_binary,
        is_too_large: file.is_too_large,
        mime_type: file.mime_type,
        name: file.name,
        path: file.path,
        size: file.size,
        text: file.text,
        ..Default::default()
    }
}

